import { Button, Input, Select, Switch } from '@jinx-ui/react';

export type InterfaceLanguage = 'ru' | 'en';

export interface ProfileSettings {
  name: string;
  language: InterfaceLanguage;
  emailNotifications: boolean;
}

export interface ProfileSettingsFormProps {
  initialSettings?: ProfileSettings;
  onSave: (settings: ProfileSettings) => void;
}

const DEFAULT_SETTINGS: ProfileSettings = {
  name: '',
  language: 'ru',
  emailNotifications: false,
};

const LANGUAGE_OPTIONS: ReadonlyArray<{ value: InterfaceLanguage; label: string }> = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'Английский' },
];

function ProfileSettingsForm({ initialSettings, onSave }: ProfileSettingsFormProps) {
  const [settings, setSettings] = useState<ProfileSettings>(initialSettings ?? DEFAULT_SETTINGS);

  const handleNameChange = (event: ChangeEvent<HTMLInputElement>) => {
    const name = event.target.value;
    setSettings((current) => ({ ...current, name }));
  };

  const handleLanguageChange = (language: InterfaceLanguage) => {
    setSettings((current) => ({ ...current, language }));
  };

  const handleNotificationsChange = (emailNotifications: boolean) => {
    setSettings((current) => ({ ...current, emailNotifications }));
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave(settings);
  };

  return (
    <form
      className="jx-form"
      onSubmit={handleSubmit}
      style={{ display: 'grid', gap: 'var(--jx-space-4)' }}
    >
