        <label className="jx-label" htmlFor="profile-settings-language">
          Язык интерфейса
        </label>
        <Select
          id="profile-settings-language"
          name="language"
          value={settings.language}
          options={LANGUAGE_OPTIONS}
          onChange={handleLanguageChange}
        />
      </div>

      <div
        className="jx-field"
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 'var(--jx-space-3)',
        }}
